import{c as o,Z as e,Q as i,j as l,m as r,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"大德歌·春","description":"","frontmatter":{"title":"大德歌·春","author":"关汉卿","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/6.md","filePath":"books/shici/yuanqu/6.md"}'),u={name:"books/shici/yuanqu/6.md"};function s(h,a,q,c,d,p){const t=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="大德歌·春" tabindex="-1">大德歌·春 <a class="header-anchor" href="#大德歌·春" aria-label="Permalink to &quot;大德歌·春&quot;">​</a></h1><p><strong>[元] <a href="/authors/guanhanqing.html">关汉卿</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>子规啼，不如归，道是春归人未归。 几日添憔悴，虚飘飘柳絮飞。 一春鱼雁无消息，则见双燕斗衔泥。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>大德歌：曲牌名</li><li>子规：杜鹃鸟，相传其啼声似说&quot;不如归去&quot;</li><li>不如归：杜鹃啼声谐音，意为不如归去</li><li>道是：说是</li><li>憔悴：形容人因忧愁而消瘦萎靡</li><li>虚飘飘：轻盈飘飞的样子</li><li>鱼雁：古代以鱼雁传书，代指书信</li><li>鱼雁无消息：没有书信音讯</li><li>则见：只见</li><li>斗衔泥：争着衔泥筑巢</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>杜鹃鸟声声啼叫，&quot;不如归去&quot;，说是春天已经归来，而远行的人却还没有回来。 连日来因相思而日渐憔悴，只见柳絮在空中虚飘飘地飞舞。 整整一个春天，都没有收到你的书信音讯，只看见一对对燕子争着衔泥筑巢。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是关汉卿《大德歌》四季组曲中的春景之作，描写思妇在春日里思念远人的情景，感情细腻，意境优美。</p><p>&quot;子规啼，不如归，道是春归人未归&quot;，以杜鹃啼声起兴。子规啼血，声声&quot;不如归去&quot;，既点明暮春时节，又勾起思妇对远人的思念。春已归来，而人未归来，对比之中更添惆怅。</p><p>&quot;几日添憔悴，虚飘飘柳絮飞&quot;，写思妇因相思而日渐憔悴，而窗外柳絮飘飞，更添纷乱心绪。&quot;虚飘飘&quot;三字，既写柳絮轻盈之态，又喻思妇空虚落寞的心境，情景交融。</p><p>&quot;一春鱼雁无消息，则见双燕斗衔泥&quot;，以&quot;鱼雁无消息&quot;写音书断绝的失望，以&quot;双燕斗衔泥&quot;反衬孤独寂寞。燕子双飞双宿，忙着筑巢，而思妇却独守空闺，连音信都没有。这种以乐景写哀情的手法，将思妇的相思之苦表现得更加深切动人。全曲语言清新，情感真挚，是元曲中描写闺情的佳作。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>关汉卿</strong>（约1234年以前－约1300年左右），号已斋叟，元代杂剧奠基人，元曲四大家之首。一生创作杂剧六十余种，现存十八种，以《窦娥冤》最为著名。</p><p><a href="/authors/guanhanqing.html">查看作者详情 →</a></p></blockquote>',16)),n(t)])}const b=o(u,[["render",s]]);export{m as __pageData,b as default};
